SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';

-- Schools, colleges and universities that tutors and students pick from. Super admins add, edit and
-- deactivate them; tutor.institute_name and tuition_requirement.institute_name stay as the text shown,
-- and institution_id links the row a pick came from (null for free text).

CREATE TYPE "InstitutionKind" AS ENUM ('SCHOOL', 'COLLEGE', 'SCHOOL_AND_COLLEGE', 'UNIVERSITY');

-- Search key: lowercase ASCII words, with common Bangla-romanisation variants folded together on both
-- sides (q/k, v/w/b, z/j, y/i, ph/f, sh/s, double letters...), so "Vikarunnisa" finds "Viqarunnisa".
CREATE FUNCTION institution_norm(p text) RETURNS text
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE
  s text := lower(coalesce(p, ''));
BEGIN
  s := replace(s, '&', ' and ');
  s := regexp_replace(s, '[^a-z0-9]+', ' ', 'g');
  s := regexp_replace(s, '\m(government)\M', 'govt', 'g');
  s := regexp_replace(s, '\m(and|of|the)\M', ' ', 'g');
  s := replace(replace(replace(replace(replace(s, 'ph', 'f'), 'sh', 's'), 'kh', 'k'), 'gh', 'g'), 'th', 't');
  s := replace(replace(replace(replace(replace(s, 'dh', 'd'), 'bh', 'b'), 'ch', 'c'), 'jh', 'j'), 'ee', 'i');
  s := replace(s, 'oo', 'u');
  s := translate(s, 'qzwvy', 'kjbbi');
  s := regexp_replace(s, '([a-z])\1+', '\1', 'g');
  RETURN btrim(regexp_replace(s, '\s+', ' ', 'g'));
END $$;

CREATE TABLE "institution" (
    -- Int ids like subject and area (a few thousand rows); serial keeps Prisma's autoincrement.
    -- squawk-ignore prefer-identity, prefer-bigint-over-int
    "id" SERIAL NOT NULL,
    "name" TEXT NOT NULL,
    "kind" "InstitutionKind" NOT NULL,
    "district" TEXT,
    "area" TEXT,
    "eiin" TEXT,
    "aliases" TEXT[] NOT NULL DEFAULT '{}',
    -- squawk-ignore prefer-bigint-over-smallint
    "popularity" SMALLINT NOT NULL DEFAULT 0,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    -- Written only by the institution_keys trigger.
    "name_key" TEXT NOT NULL DEFAULT '',
    "alias_keys" TEXT[] NOT NULL DEFAULT '{}',
    "search_text" TEXT NOT NULL DEFAULT '',
    -- First letters of the name's words after folding ("Viqarunnisa Noon School & College" -> "bnsc").
    "initials_key" TEXT NOT NULL DEFAULT '',
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),

    CONSTRAINT "institution_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "institution_name_length" CHECK (char_length(btrim("name")) BETWEEN 2 AND 150),
    CONSTRAINT "institution_aliases_count" CHECK (cardinality("aliases") <= 20)
);

CREATE FUNCTION institution_keys() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.name_key := institution_norm(NEW.name);
  NEW.alias_keys := ARRAY(
    SELECT DISTINCT k FROM (SELECT institution_norm(a) AS k FROM unnest(NEW.aliases) AS a) s WHERE k <> '');
  NEW.search_text := btrim(NEW.name_key || ' ' || array_to_string(NEW.alias_keys, ' '));
  NEW.initials_key := coalesce((
    SELECT string_agg(left(w, 1), '' ORDER BY n)
    FROM unnest(string_to_array(NEW.name_key, ' ')) WITH ORDINALITY AS t(w, n)
    WHERE w ~ '^[a-z]'), '');
  RETURN NEW;
END $$;

CREATE TRIGGER institution_keys_trg BEFORE INSERT OR UPDATE OF "name", "aliases" ON "institution"
  FOR EACH ROW EXECUTE FUNCTION institution_keys();

-- The table is new and empty, so plain index builds are fine.
-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX "institution_eiin_key" ON "institution"("eiin");
-- One row per name in one area (BANBEIS repeats names across thanas).
-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX "institution_name_area_key" ON "institution"("name_key", (coalesce(lower("area"), '')));
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "institution_search_trgm" ON "institution" USING gin ("search_text" gin_trgm_ops);
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "institution_alias_keys_gin" ON "institution" USING gin ("alias_keys");

-- Default list. Universities: Wikipedia "List of universities in Bangladesh" (UGC-listed, Nov 2026).
-- Dhaka district schools and colleges: BANBEIS e-survey 2024 school and college lists, with spelling
-- fixed and well-known short names added (government primary schools rank lower). Plus institutions
-- missing from those lists: well-known Dhaka English-medium schools (not board-listed), medical and dental
-- colleges, the cadet colleges and the large colleges outside Dhaka. A bad row fails the migration.

-- Ids above 100000 are created by admins (and by tests, which delete them).
SELECT setval(pg_get_serial_sequence('"institution"', 'id'), 100000);

-- squawk-ignore prefer-bigint-over-int
ALTER TABLE "tutor" ADD COLUMN "institution_id" INTEGER;
-- squawk-ignore prefer-bigint-over-int
ALTER TABLE "tuition_requirement" ADD COLUMN "institution_id" INTEGER;
-- squawk-ignore adding-foreign-key-constraint
ALTER TABLE "tutor" ADD CONSTRAINT "tutor_institution_id_fkey" FOREIGN KEY ("institution_id")
  REFERENCES "institution"("id") ON DELETE SET NULL ON UPDATE CASCADE NOT VALID;
-- squawk-ignore adding-foreign-key-constraint
ALTER TABLE "tuition_requirement" ADD CONSTRAINT "tuition_requirement_institution_id_fkey" FOREIGN KEY ("institution_id")
  REFERENCES "institution"("id") ON DELETE SET NULL ON UPDATE CASCADE NOT VALID;
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "tutor_institution_id_idx" ON "tutor"("institution_id");
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "tuition_requirement_institution_id_idx" ON "tuition_requirement"("institution_id");
